import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root group for the card
  const group = new THREE.Group();
  group.position.set(2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Card dimensions (portrait aspect ~1.6:1 for thumbnail)
  const cardWidth = 1.2;
  const cardHeight = 1.9;

  // Create plane geometry for the card
  const geometry = new THREE.PlaneGeometry(cardWidth, cardHeight);

  // Load image texture
  let texture = null;
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    texture = tex;
    texture.colorSpace = THREE.SRGBColorSpace;
    material.colorNode = tex;
    material.needsUpdate = true;
  });

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.FrontSide,
    colorNode: vec3(0.1, 0.1, 0.1), // Placeholder dark gray
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  group.add(mesh);

  // Create accent edge: thin red border plane slightly in front
  const borderGeometry = new THREE.PlaneGeometry(cardWidth + 0.08, cardHeight + 0.08);
  const borderMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 0,
    transparent: true,
    opacity: 0,
    side: THREE.FrontSide,
  });
  const borderMesh = new THREE.Mesh(borderGeometry, borderMaterial);
  borderMesh.position.z = -0.01;
  borderMesh.renderOrder = -1;
  group.add(borderMesh);

  // State tracking
  let isHovered = false;
  let isPressed = false;
  let timeline = null;
  let borderTimeline = null;

  // Event handlers
  const handlers = {
    onPointerEnter() {
      if (isHovered) return;
      isHovered = true;

      // Kill existing timeline
      if (timeline) timeline.kill();

      // Rise-in effect: lift 0.15 units, subtle 0.5s ease
      timeline = gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.5,
        ease: 'power2.out',
      });

      // Accent edge fade in
      if (borderTimeline) borderTimeline.kill();
      borderTimeline = gsap.to(borderMaterial, {
        opacity: 0.8,
        emissiveIntensity: 1.2,
        duration: 0.3,
        ease: 'power2.out',
      });
    },

    onPointerLeave() {
      if (!isHovered) return;
      isHovered = false;

      if (timeline) timeline.kill();

      // Return to original position
      timeline = gsap.to(group.position, {
        y: 1.6,
        duration: 0.6,
        ease: 'power3.out',
      });

      // Accent edge fade out
      if (borderTimeline) borderTimeline.kill();
      borderTimeline = gsap.to(borderMaterial, {
        opacity: 0,
        emissiveIntensity: 0,
        duration: 0.4,
        ease: 'power2.inOut',
      });
    },

    onPointerDown() {
      if (isPressed) return;
      isPressed = true;

      if (timeline) timeline.kill();
      timeline = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },

    onPointerUp() {
      if (!isPressed) return;
      isPressed = false;

      if (timeline) timeline.kill();
      timeline = gsap.to(group.scale, {
        x: 1,
        y: 1,
        duration: 0.4,
        ease: 'power3.out',
      });
    },

    onClick() {
      ctx.emit('hub-journal.select', { timestamp: Date.now() });
    },
  };

  // Attach handlers to group for raycasting
  group.userData.handlers = handlers;
  group.userData.interactive = true;
  group.userData.raycasterPriority = 10;

  // Cleanup function
  group.userData.cleanup = () => {
    if (timeline) timeline.kill();
    if (borderTimeline) borderTimeline.kill();
    geometry.dispose();
    borderGeometry.dispose();
    material.dispose();
    borderMaterial.dispose();
    if (texture) texture.dispose();
  };

  return group;
}
